-- Restores the registration client UI specs that the master data loader truncates.
--
-- The loader reads mosip_master/xlsx/ui_spec.xlsx, and an Excel cell holds at most 32,767
-- characters. The New, Update and Lost Registration specs are longer, so they are loaded cut
-- short (invalid JSON) and registration clients cannot use them. This writes the full specs
-- back; the settings and Biometric correction specs fit and are left to the loader.
-- New Registration includes the change hiding Address Proof (proofOfAddress). All three carry the
-- reviewed English, Sinhala and Tamil labels (label-context, 2026-10-30).
--
-- When: once, after the master data loader has run on a new environment (the loader itself runs
-- only once per environment).
--
-- Which rows: the ones the registration clients receive, found the way masterdata finds them
-- (admin-services release-1.2.0, IdentitySchemaServiceImpl.getLatestPublishedSchema with
-- schemaVersion 0, called by the client sync syncdata/latestidschema):
--   1. the identity schema: highest id_version that is PUBLISHED, active and not deleted;
--   2. for each spec type, the ui_spec row in domain registration-client for that identity schema
--      with the highest version (UISpecRepository.findTypesByDomainAndSchema; masterdata does not
--      check its status or is_active, so a newer DRAFT row is the one clients get).
-- Rows are found by type, not id, so the script works whatever ids an environment has.
-- It only reads and updates master.ui_spec; it creates nothing. Safe to run again: a spec that
-- already matches is left alone.
--
-- How to run (plain PostgreSQL SQL; run the whole file, top to bottom):
--   psql:    psql -X -v ON_ERROR_STOP=1 -h <host> -U <user> -d mosip_master -f <this file>
--            Autocommit (psql's default) commits the update when it succeeds; on any error nothing
--            is written and psql exits non-zero, so it can run in a job or pipeline. -X ignores a
--            .psqlrc, which could turn autocommit off and leave the update uncommitted.
--   DBeaver: open the file on the mosip_master connection and Execute SQL Script (Alt+X).
--            With Auto-Commit off, press Commit afterwards (Rollback if it failed).
--            Messages are in the Output panel.
-- The update is a single statement: all specs are written, or on any error none are.
--
-- After it succeeds: restart the kernel masterdata and syncdata pods, then sync the
-- registration clients (they fetch the whole schema and specs on every sync).
--
-- Contents (generated by build_restore_sql.pl from specs/; do not edit by hand):
--   newProcess      39200 bytes  md5 7b1de14aae11ecf472e25b887b688441
--   updateProcess   38564 bytes  md5 9fbec5f0e37eafbcc32f5e57de8002ef
--   lostProcess     38386 bytes  md5 2f2b542e9568e66b9a90ee51c2bc88ba
--
SET client_encoding = 'UTF8';
DO $update_specs$
DECLARE
    r record;
    t record;
    v_schema_id varchar;
    v_schema_count integer;
    v_rows integer;
    v_updated integer := 0;
    v_unchanged integer := 0;
BEGIN
    -- 1. The identity schema the clients receive.
    SELECT count(DISTINCT s.id), min(s.id) INTO v_schema_count, v_schema_id
    FROM master.identity_schema s
    WHERE s.id_version = (SELECT max(b.id_version) FROM master.identity_schema b
                      WHERE NOT coalesce(b.is_deleted, false) AND b.is_active AND b.status_code = 'PUBLISHED');
    IF v_schema_count = 0 THEN
        RAISE EXCEPTION 'no PUBLISHED, active identity schema in master.identity_schema';
    END IF;
    IF v_schema_count > 1 THEN
        RAISE EXCEPTION '% identity schemas share the latest published version; fix the duplicates first', v_schema_count;
    END IF;
    FOR r IN SELECT x.type, x.expected_md5, convert_from(decode(x.spec_base64, 'base64'), 'UTF8') AS json_spec
             FROM (VALUES
        ('newProcess', '7b1de14aae11ecf472e25b887b688441', '
