            InJpZ2h0TWlkZGxlIiwibGVmdEluZGV4IiwibGVmdExpdHRsZSIsImxlZnRSaW5nIiwibGVmdE1p
            ZGRsZSIsImxlZnRUaHVtYiIsInJpZ2h0VGh1bWIiLCJmYWNlIl19XSwicmVxdWlyZWQiOmZhbHNl
            LCJiaW9BdHRyaWJ1dGVzIjpbImxlZnRFeWUiLCJyaWdodEV5ZSIsInJpZ2h0SW5kZXgiLCJyaWdo
            dExpdHRsZSIsInJpZ2h0UmluZyIsInJpZ2h0TWlkZGxlIiwibGVmdEluZGV4IiwibGVmdExpdHRs
            ZSIsImxlZnRSaW5nIiwibGVmdE1pZGRsZSIsImxlZnRUaHVtYiIsInJpZ2h0VGh1bWIiLCJmYWNl
            Il0sInJlcXVpcmVkT24iOlt7ImVuZ2luZSI6Ik1WRUwiLCJleHByIjoiaWRlbnRpdHkuZ2V0KCdh
            Z2VHcm91cCcpID09ICdJTkZBTlQnIn1dLCJzdWJUeXBlIjoiaW50cm9kdWNlciIsImV4Y2VwdGlv
            blBob3RvUmVxdWlyZWQiOmZhbHNlfV0sImxheW91dFRlbXBsYXRlIjpudWxsLCJwcmVSZWdGZXRj
            aFJlcXVpcmVkIjpmYWxzZSwiYWRkaXRpb25hbEluZm9SZXF1ZXN0SWRSZXF1aXJlZCI6ZmFsc2Us
            ImFjdGl2ZSI6ZmFsc2V9XSwiY2FwdGlvbiI6eyJ0YW0iOiLgrofgrrTgrqjgr43grqQgU0xVREkg
            4K6O4K6j4K+NIiwic2luIjoi4Lax4LeQ4Lat4LeS4LeA4LeWIFNMVURJIOC2heC2guC2muC2uiIs
            ImVuZyI6Ikxvc3QgVUlOIn0sImljb24iOiJMb3N0VUlOLnBuZyIsImF1dG9TZWxlY3RlZEdyb3Vw
            cyI6bnVsbCwiaXNBY3RpdmUiOmZhbHNlfQ==')
    ) AS x(type, expected_md5, spec_base64)
    LOOP
        -- The spec must have arrived exactly as generated, and be valid JSON.
        IF md5(r.json_spec) <> r.expected_md5 THEN
            RAISE EXCEPTION '% spec does not match its checksum; the script file was changed or cut short', r.type;
        END IF;
        PERFORM r.json_spec::jsonb;
        -- 2. The highest-version ui_spec row of that identity schema for this type.
        SELECT min(u.id) AS id, max(u.version) AS version, count(*) AS rows_at_version,
               min(u.status_code) AS status_code, bool_and(u.is_active) AS is_active,
               bool_and(md5(u.json_spec) = r.expected_md5) AS up_to_date
        INTO t
        FROM master.ui_spec u
        WHERE u.domain = 'registration-client' AND u.identity_schema_id = v_schema_id AND u.type = r.type
          AND u.version = (SELECT max(m.version) FROM master.ui_spec m
                           WHERE m.domain = 'registration-client' AND m.identity_schema_id = v_schema_id AND m.type = r.type);
        IF t.rows_at_version = 0 THEN
            RAISE EXCEPTION 'no registration-client % row for identity schema % in master.ui_spec; check that the master data loader has run', r.type, v_schema_id;
        END IF;
        IF t.rows_at_version > 1 THEN
            RAISE EXCEPTION '% registration-client % rows share the highest version %; fix the duplicates first', t.rows_at_version, r.type, t.version;
        END IF;
        -- Masterdata sends the row whatever its status; the client uses the spec's own "isActive" to
        -- offer the process. An inactive row for a process the spec also disables is expected.
        IF t.status_code IS DISTINCT FROM 'PUBLISHED' OR NOT t.is_active THEN
            IF NOT t.is_active AND (r.json_spec::jsonb ->> 'isActive') = 'false' THEN
                RAISE NOTICE '% row is inactive and the spec has isActive = false: the process is disabled on the clients', r.type;
            ELSE
                RAISE WARNING '% row % (version %) is % and is_active = %, but the spec has isActive = %; masterdata still sends it to the clients',
                    r.type, t.id, t.version, t.status_code, t.is_active, coalesce(r.json_spec::jsonb ->> 'isActive', 'not set');
            END IF;
        END IF;
        IF t.up_to_date THEN
            v_unchanged := v_unchanged + 1;
            RAISE NOTICE '% -> row % version %: already up to date', r.type, t.id, t.version;
            CONTINUE;
        END IF;
        UPDATE master.ui_spec u
        SET json_spec  = r.json_spec,
            upd_by     = 'superadmin',
            upd_dtimes = now() AT TIME ZONE 'utc'
        WHERE u.id = t.id AND u.version = t.version;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows <> 1 THEN
            RAISE EXCEPTION '% row % version %: % rows updated, expected 1', r.type, t.id, t.version, v_rows;
        END IF;
        v_updated := v_updated + 1;
        RAISE NOTICE '% -> row % version %: updated', r.type, t.id, t.version;
    END LOOP;
    RAISE NOTICE 'Updated % of 3 UI specs, % already up to date (identity schema %)', v_updated, v_unchanged, v_schema_id;
END
$update_specs$;
-- Result (read only): the row the clients receive for each type. Expect 3 rows, up_to_date = true.
WITH x(type, expected_md5) AS (VALUES
    ('newProcess', '7b1de14aae11ecf472e25b887b688441'),
    ('updateProcess', '9fbec5f0e37eafbcc32f5e57de8002ef'),
    ('lostProcess', '2f2b542e9568e66b9a90ee51c2bc88ba')
),
served_schema AS (
    SELECT DISTINCT s.id FROM master.identity_schema s
    WHERE s.id_version = (SELECT max(b.id_version) FROM master.identity_schema b
                      WHERE NOT coalesce(b.is_deleted, false) AND b.is_active AND b.status_code = 'PUBLISHED')
),
served AS (
    SELECT u.* FROM master.ui_spec u JOIN served_schema sc ON sc.id = u.identity_schema_id
    WHERE u.domain = 'registration-client'
      AND u.version = (SELECT max(m.version) FROM master.ui_spec m
                       WHERE m.domain = u.domain AND m.identity_schema_id = u.identity_schema_id AND m.type = u.type)
)
SELECT x.type, u.id, u.version, u.identity_schema_id, octet_length(u.json_spec) AS bytes,
       md5(u.json_spec) = x.expected_md5 AS up_to_date,
       u.status_code, u.is_active, u.upd_by, u.upd_dtimes
FROM x LEFT JOIN served u ON u.type = x.type
ORDER BY x.type;
